:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #e0e0f0;
  --bar: #4a6fa5;
  --bar-compare: #f2a65a;
  --bar-sorted: #6bbf59;
  --btn-bg: #3a3a5a;
  --btn-hover: #4a4a6a;
  --btn-active: #2a2a4a;
  --focus: #f2a65a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  font-weight: 700;
}

.subtitle {
  text-align: center;
  font-size: 1rem;
  opacity: 0.8;
}

.bars-container {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 4px;
  height: 200px;
  padding: 8px 0;
  border-bottom: 2px solid var(--text);
  border-radius: 4px;
}

.bar {
  flex: 1;
  max-width: 40px;
  background: var(--bar);
  border-radius: 4px 4px 0 0;
  transition: height 0.2s ease, background-color 0.2s ease;
  position: relative;
}

.bar.compare {
  background: var(--bar-compare);
}

.bar.sorted {
  background: var(--bar-sorted);
}

.bar .label {
  position: absolute;
  bottom: -20px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 0.75rem;
  color: var(--text);
  opacity: 0.7;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1rem;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  background: var(--btn-bg);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  min-width: 100px;
}

button:hover {
  background: var(--btn-hover);
}

button:active {
  background: var(--btn-active);
  transform: scale(0.97);
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.message {
  text-align: center;
  font-size: 1.125rem;
  font-weight: 600;
  min-height: 1.5em;
  color: var(--bar-sorted);
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .bars-container {
    height: 160px;
  }
  button {
    padding: 10px 16px;
    min-width: 80px;
  }
}

const NUM_BARS = 10;
const MIN_HEIGHT = 10;
const MAX_HEIGHT = 100;

let values = [];
let i = 0;
let j = 0;
let sortedBoundary = NUM_BARS;
let isSorting = false;
let sorted = false;

const barsContainer = document.getElementById('bars-container');
const shuffleBtn = document.getElementById('shuffle-btn');
const stepBtn = document.getElementById('step-btn');
const messageEl = document.getElementById('message');

function randomValues() {
  const arr = [];
  for (let k = 0; k < NUM_BARS; k++) {
    arr.push(Math.floor(Math.random() * (MAX_HEIGHT - MIN_HEIGHT + 1)) + MIN_HEIGHT);
  }
  return arr;
}

function render() {
  barsContainer.innerHTML = '';
  values.forEach((val, idx) => {
    const bar = document.createElement('div');
    bar.className = 'bar';
    bar.style.height = `${val}%`;
    bar.dataset.index = idx;
    if (idx >= sortedBoundary) {
      bar.classList.add('sorted');
    }
    if (isSorting && idx === j && idx < sortedBoundary) {
      bar.classList.add('compare');
    }
    if (isSorting && idx === j + 1 && idx < sortedBoundary) {
      bar.classList.add('compare');
    }
    const label = document.createElement('span');
    label.className = 'label';
    label.textContent = val;
    bar.appendChild(label);
    barsContainer.appendChild(bar);
  });
}

function resetSort() {
  i = 0;
  j = 0;
  sortedBoundary = NUM_BARS;
  isSorting = false;
  sorted = false;
  messageEl.textContent = '';
}

function shuffle() {
  values = randomValues();
  resetSort();
  render();
  stepBtn.disabled = false;
}

function step() {
  if (sorted) return;

  if (!isSorting) {
    isSorting = true;
    j = 0;
  }

  if (j >= sortedBoundary - 1) {
    sortedBoundary--;
    j = 0;
    if (sortedBoundary <= 1) {
      sorted = true;
      isSorting = false;
      messageEl.textContent = '🎉 Sorted!'; 
      render();
      stepBtn.disabled = true;
      return;
    }
  }

  if (values[j] > values[j + 1]) {
    [values[j], values[j + 1]] = [values[j + 1], values[j]];
  }

  render();

  j++;

  if (j >= sortedBoundary - 1) {
    sortedBoundary--;
    j = 0;
    if (sortedBoundary <= 1) {
      sorted = true;
      isSorting = false;
      messageEl.textContent = '🎉 Sorted!';
      render();
      stepBtn.disabled = true;
    }
  }
}

shuffleBtn.addEventListener('click', shuffle);
stepBtn.addEventListener('click', step);

shuffle();
